# Emit fresh Count1 or Count20 config from explicit measured joins; no execution.
param([Parameter(Mandatory=$true)][ValidateSet(1,20)][int]$Count,[Parameter(Mandatory=$true)][string]$OutputRoot,[Parameter(Mandatory=$true)][string]$SourceInputsPath,[Parameter(Mandatory=$true)][string]$SourceInputsHash,[Parameter(Mandatory=$true)][string]$PlanPath,[Parameter(Mandatory=$true)][string]$PlanHash,[Parameter(Mandatory=$true)][string]$CompileReceiptPath,[Parameter(Mandatory=$true)][string]$CompileReceiptHash,[Parameter(Mandatory=$true)][string]$ExePath,[Parameter(Mandatory=$true)][string]$ExeHash,[Parameter(Mandatory=$true)][string]$RendererPath,[Parameter(Mandatory=$true)][string]$RendererSha256,[Parameter(Mandatory=$true)][string]$SerializerPath,[Parameter(Mandatory=$true)][string]$SerializerSha256,[Parameter(Mandatory=$true)][string]$HelperManifestPath,[Parameter(Mandatory=$true)][string]$HelperManifestHash,[Parameter(Mandatory=$true)][string]$Owner)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath($OutputRoot);if(Test-Path $root){throw 'fresh output root required'};New-Item -ItemType Directory -Path $root -Force|Out-Null
function Pin([string]$p,[string]$h){if($h -notmatch '^[0-9a-f]{64}$'){throw 'lowercase hash required'};$i=Get-Item -LiteralPath $p -Force;if($i.PSIsContainer -or $i.LinkType){throw 'regular file required'};if((Get-FileHash $p).Hash.ToLowerInvariant() -cne $h){throw "hash drift: $p"};[ordered]@{path=[IO.Path]::GetFullPath($p);sha256=$h;bytes=[int64]$i.Length}}
$src=Pin $SourceInputsPath $SourceInputsHash;$plan=Pin $PlanPath $PlanHash;$rec=Pin $CompileReceiptPath $CompileReceiptHash;$exe=Pin $ExePath $ExeHash;$rend=Pin $RendererPath $RendererSha256;$ser=Pin $SerializerPath $SerializerSha256;$helpers=Pin $HelperManifestPath $HelperManifestHash
$out=[ordered]@{kind="factory-padding-count${Count}-config-v1";count=$Count;controlRoot=$root;outputRoot=(Join-Path $root 'output');runRoot=(Join-Path $root 'output\run');owner=$Owner;sourceInputsPath=$src.path;sourceInputsHash=$src.sha256;planPath=$plan.path;planHash=$plan.sha256;compileReceiptPath=$rec.path;compileReceiptHash=$rec.sha256;exePath=$exe.path;exeHash=$exe.sha256;rendererPath=$rend.path;rendererSha256=$rend.sha256;serializerPath=$ser.path;serializerControlSha256=$ser.sha256;helperManifestPath=$helpers.path;helperManifestHash=$helpers.sha256;memoryLimitBytes=1073741824;limitFlags=512;killOnJobClose=$false;closeSeconds=15;drainSeconds=5;noActivate=$true;nativeActions=0;lockActions=0}
$out|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $root "count${Count}-config.json") -Encoding UTF8
$out|ConvertTo-Json -Depth 10
